#!/usr/bin/env node
/**
 * READ-ONLY Live Auth E2E against the existing dedicated Supabase staging project.
 * Uses genuine sessions generated by signInWithPassword via @supabase/ssr cookies.
 * Never prints passwords, cookies, user IDs or JWTs; never runs against Production.
 * Partial (two-role) mode is explicitly NOT a full three-role acceptance.
 */
import assert from "node:assert/strict";
import {createClient} from "@supabase/supabase-js";
import {createServerClient} from "@supabase/ssr";
import {resolve} from "node:path";
import {fileURLToPath} from "node:url";
import {readRlsConfig} from "./verify-roadmap-rls.mjs";

export const AUTH_STAGING_REF="ordiksbvpewwgrnvzrud";
const previewHostname=/^xuong-cong-nghe-[a-z0-9]+-huunghia160699-5603\.vercel\.app$/;
const options={auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}};

export function readAuthQaConfig(env){
 // This helper checks for an explicit public/publishable key and two unique users.
 const cfg=readRlsConfig(env,false);
 const supabaseUrl=new URL(cfg.url);
 if(env.RLS_TEST_PROJECT_REF!==AUTH_STAGING_REF||
    supabaseUrl.hostname!==AUTH_STAGING_REF+".supabase.co"||
    supabaseUrl.pathname!=="/"||supabaseUrl.search||supabaseUrl.hash)
   throw new Error("AUTH QA chỉ được chạy trên Supabase staging đã chỉ định.");
 let preview;
 try{preview=new URL(env.AUTH_QA_PREVIEW_URL);}catch{throw new Error("Thiếu AUTH_QA_PREVIEW_URL hợp lệ.");}
 if(preview.protocol!=="https:"||!previewHostname.test(preview.hostname)||
    preview.port||preview.pathname!=="/"||preview.search||preview.hash||
    preview.username||preview.password)
   throw new Error("Chỉ cho phép URL triển khai Vercel Preview, không chạy trên Production hoặc website khác.");
 const teacherEmail=(env.RLS_TEACHER_EMAIL??"").trim();
 const teacherPassword=env.RLS_TEACHER_PASSWORD??"";
 const hasTeacher=Boolean(teacherEmail&&teacherPassword);
 if(!hasTeacher&&env.AUTH_QA_ALLOW_PARTIAL!=="YES")
   throw new Error("BLOCKED: Thiếu Teacher QA thật. Có thể dùng AUTH_QA_ALLOW_PARTIAL=YES để thử 2 vai trò mà KHÔNG đánh dấu hoàn tất.");
 if(hasTeacher&&[cfg.adminEmail,cfg.studentEmail].some(x=>x.toLowerCase()===teacherEmail.toLowerCase()))
   throw new Error("Teacher QA phải là tài khoản riêng, không dùng chung Admin/Student.");
 return {...cfg,preview:preview.origin,teacherEmail,teacherPassword,hasTeacher};
}

function makeSession(url,key){
 const jar=new Map();
 const client=createServerClient(url,key,{
  cookies:{
   getAll(){return [...jar].map(([name,value])=>({name,value}));},
   setAll(items){for(const {name,value} of items){if(value)jar.set(name,value);else jar.delete(name);}}
  },
  auth:{autoRefreshToken:false,detectSessionInUrl:false}
 });
 return {client,jar};
}

async function readRoute(origin,path,jar,fetchImpl){
 const headers={Accept:"text/html"};
 // Vercel Deployment Protection: optional QA-only bypass header in local secret env.
 if(process.env.AUTH_QA_VERCEL_BYPASS)headers["x-vercel-protection-bypass"]=process.env.AUTH_QA_VERCEL_BYPASS;
 if(jar?.size)headers.Cookie=[...jar].map(([name,value])=>name+"="+encodeURIComponent(value)).join("; ");
 const response=await fetchImpl(origin+path,{method:"GET",redirect:"manual",headers,cache:"no-store"});
 if(response.status===401&&response.headers.get("content-type")?.includes("text/html"))
   throw new Error("Preview bị Vercel Authentication chặn: mở quyền truy cập QA trước, không nhầm với 401 của ứng dụng.");
 return response;
}

async function assertRedirect(origin,path,target,jar,fetchImpl){
 const res=await readRoute(origin,path,jar,fetchImpl);
 assert.ok([302,303,307,308].includes(res.status),
  path+" phải redirect nhưng trả "+res.status);
 const url=new URL(res.headers.get("location")??"",origin);
 assert.equal(url.origin,origin,"Redirect không được nhảy sang domain khác");
 assert.equal(url.pathname,target,path+" redirected to wrong destination");
 if(target==="/dang-nhap")assert.equal(url.searchParams.get("next"),path,"Thiếu next path khi đăng nhập");
}

async function assertPage(origin,path,jar,fetchImpl){
 const res=await readRoute(origin,path,jar,fetchImpl);
 assert.equal(res.status,200,path+" phải cho phép tài khoản hợp lệ truy cập");
 const html=await res.text();
 assert.ok(!html.includes('name="password"'),path+" bất ngờ hiển thị form đăng nhập");
}

async function assertApi(origin,path,expected,jar,fetchImpl){
 const res=await readRoute(origin,path,jar,fetchImpl);
 assert.equal(res.status,expected,path+" HTTP status khác dự kiến");
}

async function signIn(config,role,email,password){
 const {client,jar}=makeSession(config.url,config.key);
 const {data,error}=await client.auth.signInWithPassword({email,password});
 assert.ok(!error&&data.session?.access_token,"Không đăng nhập được tài khoản QA "+role);
 const {data:{user},error:whoError}=await client.auth.getUser();
 assert.ok(!whoError&&user?.email_confirmed_at,"JWT/email chưa xác minh cho "+role);
 const {data:profile,error:profileError}=await client.from("profiles").select("role").eq("id",user.id).single();
 assert.ok(!profileError&&profile?.role===role,"profiles.role không khớp "+role);
 const {data:visible,error:visibleError}=await client.from("profiles").select("id");
 assert.ok(!visibleError,"Không đọc được hồ sơ "+role);
 if(role!=="admin")assert.ok((visible??[]).length===1&&(visible??[])[0].id===user.id,
  role+" thấy hồ sơ không thuộc quyền sở hữu");
 return {client,jar};
}

export async function runAuthStagingQa({env=process.env,fetchImpl=fetch,log=console.log}={}){
 const config=readAuthQaConfig(env); // Fail closed before any sign-in/network call.
 const guest=createClient(config.url,config.key,options);
 for(const path of ["/","/tin-tuc","/cong-cu","/cong-cu/trinh-chieu"])
  await assertPage(config.preview,path,null,fetchImpl);
 for(const path of ["/student","/student/quiz","/admin","/admin/roadmap",
   "/cong-cu/mo-phong-word","/cong-cu/trinh-chieu/quan-ly-tep-va-thu-muc"])
  await assertRedirect(config.preview,path,"/dang-nhap",null,fetchImpl);
 for(const path of ["/api/admin/roadmap","/api/admin/roadmap/backup","/api/quiz/nonexistent"])
  await assertApi(config.preview,path,401,null,fetchImpl);
 const {error:guestRoadmap}=await guest.from("admin_roadmap").select("id");
 assert.ok(guestRoadmap,"Khách không được SELECT Admin Roadmap");
 log("PASS guest: public routes available; tool/admin/student gated; API 401; RLS denied.");

 const admin=await signIn(config,"admin",config.adminEmail,config.adminPassword);
 const student=await signIn(config,"student",config.studentEmail,config.studentPassword);
 const teacher=config.hasTeacher
  ? await signIn(config,"teacher",config.teacherEmail,config.teacherPassword):null;
 for(const [role,session] of [["admin",admin],["student",student],...(teacher?[["teacher",teacher]]:[])]){
  for(const path of ["/student","/student/quiz","/cong-cu/mo-phong-word",
    "/cong-cu/trinh-chieu/quan-ly-tep-va-thu-muc"])
   await assertPage(config.preview,path,session.jar,fetchImpl);
  await assertApi(config.preview,"/api/quiz/nonexistent",404,session.jar,fetchImpl);
  const {data:roadmap,error:roadmapError}=await session.client.from("admin_roadmap").select("id");
  assert.ok(!roadmapError,"Roadmap RLS read error for "+role);
  assert.equal((roadmap??[]).length,role==="admin"?1:0,"Roadmap RLS role mismatch "+role);
  if(role==="admin"){
   await assertPage(config.preview,"/admin",session.jar,fetchImpl);
   await assertApi(config.preview,"/api/admin/roadmap",200,session.jar,fetchImpl);
   await assertApi(config.preview,"/api/admin/roadmap/backup",200,session.jar,fetchImpl);
  }else{
   await assertRedirect(config.preview,"/admin","/khong-co-quyen",session.jar,fetchImpl);
   await assertApi(config.preview,"/api/admin/roadmap",403,session.jar,fetchImpl);
   await assertApi(config.preview,"/api/admin/roadmap/backup",403,session.jar,fetchImpl);
  }
  log("PASS "+role+": real JWT, profile RLS, pages and API read-only.");
 }
 // Cookie removal is a local session test, not the application's signOutAction.
 student.jar.clear();
 await assertRedirect(config.preview,"/student","/dang-nhap",student.jar,fetchImpl);
 log("PASS: dropping local session cookies revokes protected page access.");
 if(!teacher){log("PARTIAL: no Teacher QA account; this is NOT a three-role acceptance.");return {complete:false,roles:["admin","student"]};}
 log("FULL PASS: Admin/Student/Teacher roles; no database writes performed.");
 return {complete:true,roles:["admin","student","teacher"]};
}
const isMain=process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url);
if(isMain){
 runAuthStagingQa().then(result=>{if(!result.complete)process.exitCode=2;})
 .catch(error=>{console.error("AUTH STAGING QA FAILED:",error.message);process.exitCode=1;});
}
